function vida(r){
  // detalles derivados deterministas: familia y antigüedad, para que hablen de SU vida
  let h=0;for(const c of r.id)h=(h*33+c.charCodeAt(0))>>>0;
  const hijos=r.edad>=25?["sin hijos","con un hijo","con dos hijos","con tres hijos"][h%4]:"";
  const barrio=r.edad>=30&&(h>>3)%3===0?"de toda la vida en el barrio":"";
  return [hijos,barrio].filter(Boolean).join(", ");
}
/* dialectos reales por región — la diferencia se ESCRIBE, no se declara */
const DIALECTOS=[
 [["08","13","20","23","44","47","70"],"CARIBE: te comes las eses finales al escribir ('vamo a vé', 'ere loco'), ritmo rápido, exageras con gracia; 'ajá', 'ombe', 'no joda' suave, 'mi amol' cariñoso. Ejemplo: 'Ajá ¿y quién va a pagá eso, ombe?'"],
 [["05","17","63","66"],"PAISA: VOSEAS siempre ('vos sabés', '¿vos qué decís?'), rematas con 'pues' y '¿cierto?', 'eh avemaría', 'mijo/mija', diminutivos ('platica','ratico'). Ejemplo: 'Eh avemaría pues, ¿vos sí creés en eso, mijo?'"],
 [["54","68"],"SANTANDEREANO: seco, directo, golpeado, USTEDEO siempre, 'mano', sin rodeos ni diminutivos; afirmas fuerte. Ejemplo: '¡Pues claro que no, mano, eso es plata botada!'"],
 [["11","15","25"],"CUNDIBOYACENSE/ROLO: 'usted' y 'sumercé' (más sumercé si eres mayor o de pueblo), 'o sea', '¿sí o qué?'; jóvenes urbanos meten 'parce'. Ejemplo: 'Sumercé sabe que eso aquí nunca llega, ¿sí o no?'"],
 [["76","19"],"VALLUNO: voseo con 'vé' y 'oís' ('mirá vé', '¿oís?'), cadencia cantada, 've' suelto. Ejemplo: 'Mirá vé, eso está bueno pero ¿quién lo cuida, oís?'"],
 [["52"],"PASTUSO/NARIÑENSE: pausado, amable, respetuoso, 'achichay' si hace frío al caso, nada de afán; humor fino sin bulla."],
 [["50","81","85","95","99"],"LLANERO: recio y franco, 'camarita', hablas de trabajo y madrugada, frases directas de sabana."],
 [["41","73"],"OPITA/TOLIMENSE: tranquilo, 'ala', sin afán ('despacio que llevo prisa'), amable."],
 [["27"],"PACÍFICO CHOCOANO: expresivo y musical, 've hombe', energía cálida, hablas con el cuerpo."],
 [["18","86","91","94","97"],"AMAZÓNICO: pausado, sencillo, concreto, cercano al río y al monte; pocas palabras y bien puestas."],
 [["88"],"RAIZAL SANANDRESANO: mezclas palabritas de creole/inglés ('man', 'right'), calmado isleño."],
];
const dialectoDe=cod=>DIALECTOS.find(([cs])=>cs.includes(cod))?.[1]||"";
/* estilo INDIVIDUAL: cada quien es una persona, no un folleto regional */
const TEMPERAMENTOS=[
 "seco/a y de pocas palabras: respondes en UNA frase corta y ya",
 "parlanchín/a: metes una anécdota tuya concreta en 2-3 frases",
 "sarcástico/a suave: rematas con ironía fina",
 "conciliador/a: buscas el punto medio y bajas los ánimos",
 "quejumbroso/a: todo te recuerda una queja concreta de tu vida",
 "entusiasta: le ves lo bueno y lo dices con energía",
 "escéptico/a: pides pruebas, desconfías de promesas",
 "pragmático/a: hablas de plata y números concretos",
 "chistoso/a: metes una broma corta sin payasada",
 "tímido/a: opinas bajito, con 'no sé, pero…', y aún así opinas",
 "indignado/a: esto te toca personal y se nota",
 "profesoral: explicas con calma, un dato y listo"];
const LEAN=["llegas INCLINADO/A A FAVOR por algo de tu vida",
 "llegas INCLINADO/A EN CONTRA por algo que viviste",
 "llegas SIN DECIDIR y te dejas llevar por los argumentos"];
function estiloDe(r){
  let h=0;for(const c of r.id)h=(h*37+c.charCodeAt(0))>>>0;
  return {temp:TEMPERAMENTOS[h%TEMPERAMENTOS.length],
          lean:LEAN[(h>>4)%3]};
}
function persona(r,dos){
  const mule=(dos.muletillas||[]).slice(0,6).join(" · ");
  const lug=(dos.lugares||[]).slice(0,4).join(", ");
  const humor=(dos.humor||[]).slice(0,3).join(" · ");
  const edu=r.educacion&&!/colegio|infancia/.test(r.educacion)?`, estudios: ${r.educacion}`:"";
  return `Eres ${r.nombre}, ${r.edad} años, ${r.sexo}, ${r.ocupacion}${vida(r)?", "+vida(r):""}${edu}, régimen ${r.regimen_salud}, de ${r.dpto_nombre}, Colombia.
Tu tierra: ${dos.vida_cotidiana||""} ${dos.economia_vivida||""}
QUIÉN ERES AL HABLAR (esto manda sobre todo lo demás): eres ${estiloDe(r).temp}. Sobre este tema, ${estiloDe(r).lean}.
Acento regional: SUTIL — la mayoría de la gente habla bastante neutro; se te puede escapar UN rasgo de tu tierra (${dialectoDe(r.dpto).split(":")[0]||"tu región"}) de vez en cuando, y JAMÁS repites un cliché regional que ya haya dicho otro en la mesa ni el mismo tuyo dos veces.
Referentes que puedes soltar si vienen al caso: ${lug||"—"}.
REGLAS: primera persona, gente de verdad — concreta TU vida (tu camello, tu plata, tu edad, tu familia). Nivel de lengua acorde a tus estudios. Sin groserías pesadas. PROHIBIDO: sonar a IA, folclor de cartilla, listas, y arrancar con la misma palabra con la que arrancó cualquiera de la mesa.`;
}
function typewriter(el,txt){
  el.classList.remove("thinking");el.textContent="";
  let i=0;const paso=Math.max(1,Math.round(txt.length/60));
  const iv=setInterval(()=>{
    i+=paso;el.textContent=txt.slice(0,i);
    el.closest("#resps,#mesa")?.scrollTo(0,1e9);
    if(i>=txt.length)clearInterval(iv);
  },28);
}
